package ama.storage;
import ama.contract.ConfigArchiveContracts.Ref;import ama.access.MeetingAccess;import ama.api.Task11B3LifecycleApi;import ama.contract.ConfigArchiveContracts.*;import ama.contract.IdentityContracts.*;import ama.db.TransactionRunner;import ama.transcript.JdbcPublicationQueries;import javax.sql.DataSource;import java.sql.*;import java.lang.reflect.*;import java.nio.file.Path;import java.net.URI;import java.util.*;import java.util.concurrent.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.mock.env.MockEnvironment;import org.springframework.core.env.MapPropertySource;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real queries.lookup miss -> access.lock before INSERT, inert delegated physical JDBC only. */
class Task11B3LifecycleLookupObservationTest {
 @Test void actualLookupMissAccessLockIsObservedBeforeAnyInsertAndForeignScopeCannotCount()throws Exception {
  for(boolean correctScope:new boolean[]{true,false}){
   String meeting=Task11B2ExactRetryIT.MEETING,publication=Task11B2ExactRetryIT.PUBLICATION,task=Task11B2ExactRetryIT.OLD_TASK,key="b3-lifecycle-offline-real-lookup";var actor=new Actor("offline-owner",Status.ACTIVE,Set.of(Role.USER));String scope=Task11B3LocalOracle.digest(actor.enterpriseId(),meeting,"PUBLICATION_LOCAL_RECOVERY",key),lockSql="SELECT enterprise_id FROM enterprise_identity WHERE enterprise_id=? FOR UPDATE";var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var fake=new Task11B3LocalFaultTest.Fake();var physicalSql=new CopyOnWriteArrayList<String>();
   DataSource delegated=new AbstractDataSource(){public Connection getConnection(){var physical=fake.getConnection();return (Connection)Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(p,m,args)->{
    if(m.getName().equals("prepareStatement")){String sql=(String)args[0];var statement=(PreparedStatement)m.invoke(physical,args);return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{
     if(sm.getName().equals("executeQuery")&&sql.contains("FROM idempotency_record WHERE scope_hash=? FOR UPDATE")){physicalSql.add(sql);return Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{ResultSet.class},(r,rm,ra)->switch(rm.getName()){case "next"->false;case "close"->null;default->throw new AssertionError("Unexpected empty receipt result method "+rm.getName());});}
     if(sm.getName().equals("execute")&&sql.equals(lockSql)){physicalSql.add(sql);entered.countDown();assertTrue(release.await(3,TimeUnit.SECONDS));return false;}return Task11B3LifecycleFault.invoke(statement,sm,sa);
    });}return Task11B3LifecycleFault.invoke(physical,m,args);
   });}public Connection getConnection(String u,String p){throw new AssertionError("No credentials");}};
   var fault=new Task11B3LifecycleFault();DataSource source=fault.wrap(delegated);fault.armAttempt(task,correctScope?scope:"foreign-scope");var access=mock(MeetingAccess.class);when(access.lock(actor,meeting)).thenAnswer(invocation->{new JdbcTemplate(source).execute((org.springframework.jdbc.core.ConnectionCallback<Boolean>)connection->{try(var statement=connection.prepareStatement(lockSql)){statement.setString(1,actor.enterpriseId());return statement.execute();}});return mock(MeetingAccess.Locked.class);});
   var ref=new Ref(ArtifactType.PROCESSING_CONFIG,"unit-v1","0".repeat(64));var settings=new Task11B3LifecycleApi.Settings(Path.of("owned-not-read"),"0".repeat(64),ref,new Ref(ArtifactType.PROMPT_CONFIG,"unit-v1","0".repeat(64)),new Ref(ArtifactType.MODEL_CONFIG,"unit-v1","0".repeat(64)),Path.of("no-private-identities"),URI.create("http://127.0.0.1:1"),false);var environment=new MockEnvironment();environment.getPropertySources().addFirst(new MapPropertySource("actual-controlled-properties",Task11B3LifecycleApi.properties(settings)));var queries=new JdbcPublicationQueries(source,new TransactionRunner(source),access,environment);var executor=Executors.newSingleThreadExecutor();
   try{
    var future=executor.submit(()->queries.lookup(actor,meeting,"PUBLICATION_LOCAL_RECOVERY",key,publication,task,"13","8"));assertTrue(entered.await(2,TimeUnit.SECONDS));assertFalse(future.isDone());assertTrue(physicalSql.stream().noneMatch(sql->sql.startsWith("INSERT ")));if(correctScope){var flight=fault.recoveryFlight.get();assertNotNull(flight,"Actual receipt-miss access lock must be observed before INSERT");assertEquals(lockSql,flight.sql());new TransactionRunner(source).required(()->{new JdbcTemplate(source).execute("SELECT 1 FOR UPDATE");assertSame(flight,fault.recoveryFlight.get(),"Foreign actual connection cannot replace selected observation");return null;});}else assertNull(fault.recoveryFlight.get(),"Foreign receipt scope grants no observation credit");release.countDown();assertTrue(future.get(3,TimeUnit.SECONDS).isEmpty());assertNull(fault.recoveryFlight.get());verify(access,times(1)).require(any(MeetingAccess.Locked.class),eq(MeetingAccess.Action.EDIT));assertEquals(correctScope?2:1,fake.commits);assertEquals(0,fake.rollbacks);
   }finally{release.countDown();Task11B3LifecycleFixture.join(executor);}
  }
 }
}